import{RECIPES}from"./culinary-data.js";export class CulinaryEngine{constructor(){this.listeners=[],this.resetState()}resetState(){this.state={score:0,coins:0,xp:0,completedOrders:0,perfectStreak:0,multiplier:1,currentOrder:null,selectedIngredients:[],timeLeft:0,maxTime:0,gameOver:!1,resultMessage:""},this.generateOrder()}subscribe(t){return this.listeners.push(t),()=>this.listeners=this.listeners.filter(e=>e!==t)}notifyListeners(){this.listeners.forEach(t=>t(this.state))}startTimer(){this.timerInterval&&clearInterval(this.timerInterval),this.timerInterval=setInterval(()=>{this.state.gameOver||(this.state.timeLeft-=1,this.state.timeLeft<=0?this.timeOut():this.notifyListeners())},1e3)}stopTimer(){this.timerInterval&&clearInterval(this.timerInterval)}generateOrder(){const t=Math.floor(Math.random()*RECIPES.length),e=RECIPES[t],s=2*Math.floor(this.state.completedOrders/2);let r=Math.max(15,e.time-s);this.state.currentOrder=e,this.state.selectedIngredients=[],this.state.timeLeft=r,this.state.maxTime=r,this.startTimer(),this.notifyListeners()}selectIngredient(t){if(this.state.gameOver)return;this.state.selectedIngredients.push(t);const e=this.state.selectedIngredients.length-1;t===this.state.currentOrder.ingredients[e]?(this.state.score+=20*this.state.multiplier,this.state.selectedIngredients.length===this.state.currentOrder.ingredients.length?this.completeOrder():this.notifyListeners()):this.wrongIngredient()}wrongIngredient(){this.state.score-=30,this.state.perfectStreak=0,this.updateMultiplier(),this.state.resultMessage="Wrong Ingredient! Penalty -30 Score. Sequence Reset.",this.state.selectedIngredients=[],this.notifyListeners()}timeOut(){this.state.score-=100,this.state.perfectStreak=0,this.updateMultiplier(),this.state.resultMessage="Time's up! Order failed. Penalty -100 Score.",this.generateOrder()}completeOrder(){this.stopTimer();const t=this.state.currentOrder;let e=t.reward*this.state.multiplier;this.state.timeLeft>t.time/2&&(e+=100),this.state.score+=e,this.state.coins+=50,this.state.xp+=100,this.state.completedOrders+=1,this.state.perfectStreak+=1,this.updateMultiplier(),this.state.resultMessage=`ORDER COMPLETE! ⭐ +${e} Score 🪙 +50 Coins ✨ +100 XP`,this.state.gameOver=!0,this.notifyListeners()}updateMultiplier(){this.state.perfectStreak>=5?this.state.multiplier=3:this.state.perfectStreak>=3?this.state.multiplier=2:this.state.multiplier=1}nextOrder(){this.state.gameOver=!1,this.state.resultMessage="",this.generateOrder()}}export const culinaryEngine=new CulinaryEngine;